<template><section class="module-page module-composed-page"><header class="module-heading"><div><h1>课程平台</h1><p>在线学习课程内容，学习进度按资源分别记录。</p></div><el-button icon="el-icon-monitor" @click="$router.push('/training-environment')">打开全部实训环境</el-button></header><div class="course-filters"><el-input v-model="keyword" clearable prefix-icon="el-icon-search" placeholder="按名称搜索" /><el-select v-model="type" clearable placeholder="课程类型"><el-option v-for="item in types" :key="item" :label="item" :value="item" /></el-select><el-select v-model="status" placeholder="学习状态"><el-option label="全部课程" value="all" /><el-option label="学习中" value="learning" /><el-option label="已完成" value="done" /></el-select></div><div class="course-grid"><article v-for="item in filtered" :key="item.course.courseId" class="course-item"><div class="course-item-head"><div><h2>{{ item.course.name }}</h2><span>{{ item.course.courseType }}</span></div><el-button size="mini" icon="el-icon-monitor" @click="$router.push({path:'/training-environment',query:{courseId:item.course.courseId}})">进入本课程实训</el-button></div><p>{{ item.course.description || '暂无课程简介' }}</p><div class="resource-list"><button v-for="resource in item.resources" :key="resource.resourceId" type="button" @click="openResource(resource)"><i :class="icon(resource.resourceType)" /><span>{{ resource.name }}</span><small>{{ resource.resourceType }} {{ progressFor(resource) }}%</small></button></div></article><div v-if="!filtered.length" class="module-empty"><div class="module-empty-inner"><i class="el-icon-reading" /><strong>暂无可用课程</strong><p>管理员发布课程后将在此显示。</p></div></div></div><el-dialog :title="activeResource ? activeResource.name : '资源预览'" :visible.sync="preview" width="760px"><div v-if="activeResource" class="resource-preview"><el-button v-if="previewUrl" size="small" icon="el-icon-link" @click="windowOpen(previewUrl)">新窗口打开</el-button><iframe v-if="previewUrl && activeResource.resourceType !== 'VIDEO'" :src="previewUrl" class="preview-frame" title="课程资源预览" /><video v-else-if="previewUrl" :src="previewUrl" controls class="preview-video" /><p v-else>正在获取授权预览地址...</p><el-progress :percentage="progress" /><el-button type="primary" @click="finishResource">标记本资源完成</el-button></div></el-dialog></section></template>
<script>
import { listUserCourses, listAdminCourses, listCourseProgress, recordCourseProgress, getCourseResourcePreviewUrl } from '@/api/Courses'
import { getRole } from '@/utils/auth'
export default { data:()=>({courses:[],progressRecords:{},keyword:'',type:'',status:'all',preview:false,activeResource:null,previewUrl:'',progress:0}), computed:{types(){return [...new Set(this.courses.map(i=>i.course.courseType))]},filtered(){return this.courses.filter(i=>{const done=(i.resources||[]).length>0&&i.resources.every(r=>this.progressFor(r)>=100);return(!this.keyword||i.course.name.includes(this.keyword))&&(!this.type||i.course.courseType===this.type)&&(this.status==='all'||(this.status==='done'?done:!done))})}},async created(){const admin=getRole()==='ADMIN';const results=admin?await Promise.all([listAdminCourses()]):await Promise.all([listUserCourses(),listCourseProgress()]);this.courses=results[0].data||[];(results[1]&&results[1].data||[]).forEach(r=>this.$set(this.progressRecords,r.resourceId,Number(r.percent||0)))},methods:{progressFor(r){return this.progressRecords[r.resourceId]||0},icon(t){return({EBOOK:'el-icon-document',VIDEO:'el-icon-video-play',PPT:'el-icon-data-board',ARCHIVE:'el-icon-folder'})[t]||'el-icon-document'},async openResource(r){this.activeResource=r;this.progress=this.progressFor(r);this.previewUrl='';this.preview=true;try{const result=await getCourseResourcePreviewUrl(r.resourceId);this.previewUrl=result.data&&result.data.previewUrl}catch(e){this.$message.error('资源预览地址获取失败')}},windowOpen(url){window.open(url,'_blank','noopener,noreferrer')},async finishResource(){if(getRole()==='ADMIN')return;await recordCourseProgress({resourceId:this.activeResource.resourceId,progressKind:this.activeResource.resourceType==='VIDEO'?'TIME':(this.activeResource.resourceType==='PPT'?'SLIDE':'PAGE'),progressValue:100,completed:true});this.progressRecords[this.activeResource.resourceId]=100;this.progress=100;this.$message.success('学习进度已记录')}}}
</script>
<style scoped>.preview-frame{display:block;width:100%;height:430px;border:1px solid var(--ui-border);margin:12px 0}.preview-video{display:block;width:100%;max-height:430px;margin:12px 0}</style>
